const prep = $('Code - parse report1').first().json;
const saved = $('Postgres - save monitor result1').first().json;
const recipients = prep.recipients ?? [];
if (!recipients.length) return [{ json: { skipped: true, reason: 'No to_receipient_phone_ids in config' } }];
function normalizeTo(value) {
  const v = String(value).trim();
  if (!v) return null;
  if (v.includes('@')) return v;
  const digits = v.replace(/\D/g, '');
  return digits ? `${digits}@s.whatsapp.net` : null;
}
const header = `📋 *${prep.monitor_name ?? 'ActionNow Report'}*\nScore: ${prep.relevance_score}/100\n\n`;
const text = header + String(prep.report_markdown ?? '').slice(0, 3500);
return recipients.map((r) => ({ json: { to: normalizeTo(r), text, monitor_result_id: saved.id, monitor_setting_id: prep.id } })).filter((x) => x.json.to);
